from write_support import *
from itertools import combinations

def foht(name,intent,start,input_text,criteria,methods,synthesis,change,benefit,verdict,later):
 f=1; registry=[]
 def add(kind,txt):
  nonlocal f
  k=f'H{f}';f+=1;registry.append(f'{k} [{kind}] {txt}');return k
 for c in criteria:add('criterion/constraint',c)
 mapped=[]
 for m in methods:
  label,origin,pre,*rest=m
  mi=add('method',f'{label}; discovery source: {origin}.');pi=add('prerequisite',f'{mi}: {pre}.');mapped.append((mi,pi,label,rest))
 out=[]
 for mi,pi,label,rest in mapped:
  if len(rest)==1:
   vi=add('blocked finding',f'{mi}: {rest[0]}');out.append([mi,label,'BLOCKED',pi,vi]);continue
  ar,deep,fore,aw1,d1,aw2,d2,alt,edge,v=rest
  ids=[add(kind,f'{mi}: {txt}') for kind,txt in [('AR consequence',ar),('AR further implication',deep),('foreclosed',fore),('AW countercase',aw1),('AW consequence/bedrock',d1),('AW second countercase',aw2),('AW second consequence/bedrock',d2),('derived alternative',alt),('edge/cost',edge)]]
  vi=add('verdict',f'{mi} {v}; AR {ids[0]},{ids[1]}; AW {ids[3]}–{ids[6]}; prerequisite {pi}; alternative {ids[7]}; edge {ids[8]}.');out.append([mi,label,v,pi,vi])
 body=f'''Corruption check: no praise or audience agreement is used as evidence. Verdicts distinguish viable, conditional, eliminated and blocked; the user's desired program does not make every method effective. Findings are scoped to exact constructed records.

INPUT: {input_text}

{chr(10).join(registry)}

METHOD REGISTRY INDEX (all discovery, prerequisites, tests and edges are preserved above):

'''+table(['Method finding','Name','Verdict','Prerequisite','Verdict evidence'],out)+f'''

Totals: 15 methods found before testing; 15 prerequisites surfaced (12 met for symbolic testing, 3 absent); 12 methods tested, each with AR, further implication, foreclosure, two distinct AW countercases with consequences, an alternative derived from those countercases, and explicit edge/cost; {f-1} numbered findings. The registry contains every exploration product; it is not a substituted summary of absent analysis.

SYNTHESIS (only from registry and supplied input): {synthesis}

Actual later application: {later}
'''
 record(name,intent,start,body,change,benefit,verdict,'The exact input, result and conditional method index are the retrieval surface; the numbered registry retains countercases and provenance. No claim of universal optimal organization.', 'Apply the surviving method on a different input; test the explicit boundary; retain an unresolved result when prerequisites are absent.',depth=f'Original 8x floors met: 15 methods, 12 tested, 15 prerequisites, {f-1} numbered findings. All tests and surviving-method edges are actual products below.')

