R='ABAB';O='AB'
def embeddings(r,o):
 return [{'kept_zero_based':list(ix),'deleted_zero_based':[i for i in range(len(r)) if i not in ix]} for ix in combinations(range(len(r)),len(o)) if ''.join(r[i] for i in ix)==o]
obs={'repeated_reference':{'reference':R,'observed':O,'all_deletion_only_explanations':embeddings(R,O)},'unique_boundary':{'reference':'ABAC','observed':'ABC','all_deletion_only_explanations':embeddings('ABAC','ABC')},'impossible_boundary':{'reference':'AB','observed':'BA','all_deletion_only_explanations':embeddings('AB','BA')}}
(D/'sequence-localization-results.json').write_text(json.dumps(obs,indent=2))
